"""Capture OAM traffic"""
from __future__ import absolute_import, division, print_function, \
    unicode_literals
import os
import subprocess
import re
from taf.ul.trs_e2e_fw.lib.global_vars import global_vars
from taf.ul.trs_e2e_fw.lib.oam.admin.admin_factory import AdminFactory
from taf.ul.trs_e2e_fw.lib.traffic.capture.tool_base import ToolBase
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from future import standard_library
from taf.ul.trs_e2e_fw.lib.utils.string_format import decode_str

standard_library.install_aliases()
logger = BackgroundLogger.Instance()


class OamCapture(ToolBase):
    """Capture OAM traffic"""
    TOOL = "oam_tool"

    def __init__(self, config, capture_device):
        self.config = config
        self.factory = AdminFactory().get_instance()
        self.capture_device = capture_device
        self.alias_password_dict = {}

    def traffic_capture_start(self, **kwargs):
        """Starts traffic capture"""
        alias = kwargs.pop("alias", "default")
        streaming_mode = kwargs.pop("mode", "streaming")
        measurement_point = kwargs.pop("measurement_point")
        uplane_capturing = kwargs.pop("uplane_capturing", True)
        self._setup_oam_ops(self.capture_device, alias)
        timeout = kwargs.pop("timeout", 120)
        if streaming_mode.lower() == "streaming":
            logger.debug("starting ip capture streaming....")
            dst_mac_addr = kwargs.pop("dst_mac_addr")
            egress_port_dn = kwargs.pop("egress_port_dn", None)
            self.factory.admin.start_ip_capture_streaming(measurement_point=measurement_point,
                                                          uplane_capturing=uplane_capturing,
                                                          dst_mac_addr=dst_mac_addr,
                                                          egress_port_dn=egress_port_dn,
                                                          timeout=timeout, connection=alias)
        else:
            logger.debug("starting ip capture file....")
            password = kwargs.pop("password", "")
            self.alias_password_dict[alias] = password
            if password:
                self.factory.admin.start_ip_capture_file(measurement_point=measurement_point,
                                                         uplane_capturing=uplane_capturing,
                                                         password=password, timeout=timeout,
                                                         connection=alias)
            else:
                self.factory.admin.start_ip_capture_file(measurement_point=measurement_point,
                                                         uplane_capturing=uplane_capturing,
                                                         timeout=timeout, connection=alias)

    def generate_capture_files(self, **kwargs):
        """Downloads the traffic capture file"""
        alias = kwargs.pop("alias", "default")
        timeout = kwargs.pop("timeout", 120)
        password = kwargs.pop("password", "")
        self._setup_oam_ops(self.capture_device, alias)
        logger.debug("stopping and downloading ip capture file....")
        dest_file = self._get_capture_dest_file(alias)
        self.factory.admin.generate_ip_capture_file(password=password, timeout=timeout,
                                                        connection=alias)
        self.factory.admin.download_ip_capture_file(target_file_name=dest_file,
                                                    timeout=timeout, connection=alias)
        return dest_file

    def traffic_capture_stop(self, **kwargs):
        """Stops the traffic capture"""
        alias = kwargs.pop("alias", "default")
        streaming_mode = kwargs.pop("mode", "streaming")
        timeout = kwargs.pop("timeout", 120)
        if streaming_mode.lower() == "streaming":
            logger.debug("stopping ip capture streaming....")
            self.factory.admin.stop_ip_capture_streaming(timeout=timeout, connection=alias)
        elif streaming_mode.lower() == "file":
            logger.debug("stopping and downloading ip capture file....")
            password = kwargs.pop("password", "")
            dest_file = self._get_capture_dest_file(alias)
            self.factory.admin.stop_ip_capture_file(timeout=timeout, connection=alias)
            self.factory.admin.generate_ip_capture_file(password=password, timeout=timeout,
                                                        connection=alias)
            self.factory.admin.download_ip_capture_file(target_file_name=dest_file,
                                                        timeout=timeout, connection=alias)
            return dest_file


    def _get_capture_dest_file(self, alias):
        dest_file = 'execution_logs/{}_{}.zip'.format(alias, get_config_variable(["bts_id"]))
        if self.alias_password_dict.get(alias) is not "":
            dest_file = 'execution_logs/{}_{}.zip.enc'.format(alias,
                                                              get_config_variable(["bts_id"]))
        if not os.path.exists(os.path.dirname(dest_file)):
            os.makedirs(os.path.dirname(dest_file))
        return dest_file

    def _setup_oam_ops(self, capture_device, alias):
        logger.debug("setting up oamops....")
        self.factory = AdminFactory.get_instance()
        dut = global_vars.alias_dut_dict.get(alias)
        logger.debug("dut {}".format(dut))
        if dut is None:
            ip = get_config_variable(['traffic_capture', capture_device, "ip"])
            username = get_config_variable(['traffic_capture', capture_device, "admin_user"])
            password = get_config_variable(['traffic_capture', capture_device, "admin_password"])
            port = get_config_variable(['traffic_capture', capture_device, "admin_port"])
            logger.info("alias={}".format(alias))

            release = self._get_build_release_on_bts()
            self.factory.admin.setup_admin(bts_host=ip, bts_port=port, username=username,
                                           password=password, use_ssl=True, release=release, name=alias)

    def _get_build_release_on_bts(self):
        """Get bts version"""
        targetbd_filename = subprocess.check_output(
            "sshpass -p oZPS0POrRieRtu ssh toor4nsn@192.168.255.129 ls /ffs/run  2>/dev/null| grep 'Target' -m 1",
            shell=True)
        targetbd_filename = decode_str(targetbd_filename)
        release = re.search('SBTS[A-Z0-9]+', targetbd_filename).group()
        logger.debug("release={}".format(release))
        return release
